	var data1 = [
	    { "col1": "1111", "col2": "2222" },
	    { "col1": "3333", "col2": "4444" }
	];
	dataList1.setJSON(data1);

	var data2 = [
	    { "name": "장그래", "age": "30", "hp": "1234", "address": "인천" },
	    { "name": "안영이", "age": "31", "hp": "2345", "address": "부산" },
	    { "name": "김동식", "age": "32", "hp": "3456", "address": "서울" },
	    { "name": "오상식", "age": "33", "hp": "4567", "address": "광주" },
	    { "name": "김동식", "age": "32", "hp": "3456", "address": "서울" }
	];		
	dataList2.setJSON(data2);
};


/*
*	다중 GridView 하나의 엑셀파일로 시트 나눠서 다운로드 
*		options 
*			options.common	: 다운로드 할 엑셀파일 정보  
*			options.excelInfo	: 시트별 다운로드 처리할 그리드뷰 정보 (array)  
*/
scwin.multiExcelDownload = function(){
	var options = {
		common: {
			fileName : "excel_multi_down.xlsx"
		},
		excelInfo: [
			{
				gridId : "grd_temp1"
				,sheetName : "첫번째 sheet"
			},
			{
				gridId : "grd_temp2"
				,sheetName : "두번째 sheet"
			}
		]
	};
	debugger;
	//GridwView 의 데이터를 엑셀 파일로 저장한다. (다중 GridView 를 하나의 엑셀파일에 저장) 
	//com.data.downloadMultipleGridView(options);

	scwin._downloadMultipleGridView(options);	            
};	


scwin.multiDataListDownload = function(){
	debugger;
	var options = {
		scope : $p.getFrame(),
		common: {
			fileName : "excel_multi_data.xlsx"
		},
		excelInfo: [
			{
				dataListId : "dataList1",
				infoArr : [{}],
				wframeId: $p.getFrameId()
			}
		]
	};

	//com.data.downloadMultipleDataList(options);

	scwin._downloadMultipleDataList(options);	
};		


scwin.btn_search_onclick = function() {
	scwin.search();

};

scwin.btn_multiDataList_onclick = function() {
	scwin.multiDataListDownload(); 
};


//=========================================================================================//
//=========================================================================================//


scwin._downloadMultipleDataList = function (optionsParam) {
	var options = {
		scope : $p.getFrame(),
		common: {
			fileName : optionsParam.common.fileName || "dataList.xlsx",
			showProcess :  optionsParam.common.showProcess || true,
			autoSizeColumn : optionsParam.common.autoSizeColumn || true,
			multipleSheet : optionsParam.common.multipleSheet || true,
			printSet : optionsParam.common.printSet || {},
			dataListDownloadURL : "http://localhost:8080/sp4_20220408/websquare/dataListToExcel.wq",
			useDataFormat: optionsParam.common.useDataFormat || true
		},
		excelInfo: []
	};

	if (optionsParam.excelInfo.length > 0) {
		var excelInfoCount = optionsParam.excelInfo.length;

		for (var idx = 0; idx < excelInfoCount; idx++) {
			var wframeId = optionsParam.excelInfo[idx].wframeId || $p.getFrameId();
			var dataListId = optionsParam.excelInfo[idx].dataListId;



			var excelInfo = {
				dataListId : dataListId,
				sheetName : optionsParam.excelInfo[idx].sheetName || dataListId,
				removeColumns : optionsParam.excelInfo[idx].removeColumns || "",
				foldColumns : optionsParam.excelInfo[idx].foldColumns || "",
				startRowIndex : optionsParam.excelInfo[idx].startRowIndex || 0,
				startColumnIndex : optionsParam.excelInfo[idx].startColumnIndex || 0,
				headerColor : optionsParam.excelInfo[idx].headerColor || "#33CCCC",
				bodyColor : optionsParam.excelInfo[idx].bodyColor || "#FFFFFF",
				wframeId : wframeId,
				scope : wframeId,
				infoArr : optionsParam.excelInfo[idx].infoArr
			};

			options.excelInfo.push(excelInfo);
		}
	} else {
		// console.log("[com.data.downloadMultipleDataList] options.excelInfo 정보가 입력되지 않았습니다.");
		return;
	}
	debugger;
	WebSquare.util.multipleDataListDownload(options);
};
